import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import Footer from '@/components/Footer.vue';
import ToggleDark from '@/components/ToggleDark.vue';
import LanguageSwitcher from '@/components/LanguageSwitcher.vue';
import { mapGetters } from 'vuex';
import backgroundManager from '@/mixins/backgroundManager';
export default {
  name: 'BaseLogin',
  mixins: [backgroundManager],
  props: {
    // 页面标题
    title: {
      type: String,
      required: true
    },
    // 输入字段配置
    fields: {
      type: Array,
      required: true
      // fields 格式: [{ key: 'username', label: '用户名', placeholder: '请输入用户名', type: 'text', showPassword: false }]
    },
    // 提交按钮文本
    submitText: {
      type: String,
      default: ''
    },
    // 背景图配置键名
    backgroundKey: {
      type: String,
      required: true
    },
    // 是否为管理端登录（影响背景样式）
    isAdmin: {
      type: Boolean,
      default: false
    },
    // 是否正在加载
    loading: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      formData: {},
      viewportHeight: 0
    };
  },
  computed: {
    ...mapGetters(['userConfig']),
    computedSubmitText() {
      return this.submitText || this.$t('login.submit');
    },
    logoUrl() {
      return this.userConfig?.logoUrl || require('@/assets/logo.png');
    },
    logoHref() {
      return this.userConfig?.logoLink || 'https://github.com/MarSeventh/CloudFlare-ImgBed';
    },
    viewportStyle() {
      // 当检测到虚拟键盘弹出时，将容器高度收缩到可见视口高度
      // 容器本身 flex 居中，高度缩小后登录卡片自然在可见区域内居中
      if (this.viewportHeight > 0) {
        return {
          height: `${this.viewportHeight}px`,
          minHeight: `${this.viewportHeight}px`
        };
      }
      return {};
    }
  },
  watch: {
    fields: {
      handler() {
        this.initFormData(true);
      },
      deep: true
    }
  },
  components: {
    Footer,
    ToggleDark,
    LanguageSwitcher
  },
  mounted() {
    // 初始化表单数据
    this.initFormData();
    // 初始化背景图
    this.initializeBackground(this.backgroundKey, '.login', !this.isAdmin, true);
    // 监听 visualViewport 变化，检测虚拟键盘弹出
    this._handleViewportResize = this.handleViewportResize.bind(this);
    if (window.visualViewport) {
      this._initialHeight = window.visualViewport.height;
      window.visualViewport.addEventListener('resize', this._handleViewportResize);
    }
  },
  beforeUnmount() {
    if (window.visualViewport && this._handleViewportResize) {
      window.visualViewport.removeEventListener('resize', this._handleViewportResize);
    }
  },
  methods: {
    initFormData(keepValues = false) {
      // 根据字段配置初始化表单数据（语言切换时保留已输入的值）
      const newFormData = {};
      this.fields.forEach(field => {
        newFormData[field.key] = keepValues ? this.formData[field.key] ?? '' : '';
      });
      this.formData = newFormData;
    },
    handleSubmit() {
      if (this.loading) return;
      // 触发父组件的提交事件，传递表单数据
      this.$emit('submit', {
        ...this.formData
      });
    },
    handleViewportResize() {
      if (!window.visualViewport) return;
      const currentHeight = window.visualViewport.height;
      // 键盘高度 = 初始视口高度 - 当前视口高度
      const keyboardHeight = this._initialHeight - currentHeight;
      // 设定阈值：视口缩小超过 150px 才认为是虚拟键盘弹出
      // 避免地址栏收缩等小幅变化误触发
      const KEYBOARD_THRESHOLD = 150;
      if (keyboardHeight > KEYBOARD_THRESHOLD) {
        this.viewportHeight = currentHeight;
      } else {
        this.viewportHeight = 0;
      }
    }
  }
};